#pragma once
#include "witness.hpp"
#include <array>
#include <vector>
#include <set>

namespace callback_witness {
struct Snapshot {
    unsigned long long applies, restores, caller;
    std::array<unsigned long long, 64> cpus;
};
struct Record {
    int run;
    const char* phase;
    std::vector<int> cpus, cores;
};
inline std::array<int, 64> physical_core;
inline std::vector<Record> records;
inline void init() {
    physical_core.fill(-1);
    DWORD bytes = 0;
    if (GetLogicalProcessorInformationEx(RelationProcessorCore, nullptr, &bytes) || GetLastError() != ERROR_INSUFFICIENT_BUFFER)
        throw std::runtime_error("witness topology size failed");
    std::vector<unsigned char> storage(bytes);
    if (!GetLogicalProcessorInformationEx(RelationProcessorCore,
            reinterpret_cast<PSYSTEM_LOGICAL_PROCESSOR_INFORMATION_EX>(storage.data()), &bytes))
        throw std::runtime_error("witness topology query failed");
    size_t offset = 0;
    int core = 0;
    while (offset < bytes) {
        auto* item = reinterpret_cast<PSYSTEM_LOGICAL_PROCESSOR_INFORMATION_EX>(storage.data() + offset);
        if (item->Relationship != RelationProcessorCore || !item->Size || offset + item->Size > bytes ||
            item->Processor.GroupCount != 1 || item->Processor.GroupMask[0].Group != 0)
            throw std::runtime_error("unsupported witness topology");
        const auto mask = item->Processor.GroupMask[0].Mask;
        for (int cpu = 0; cpu < 64; ++cpu) {
            if (!(mask & (DWORD_PTR(1) << cpu))) continue;
            if (physical_core[size_t(cpu)] != -1) throw std::runtime_error("duplicate topology CPU");
            physical_core[size_t(cpu)] = core;
        }
        ++core;
        offset += item->Size;
    }
}
inline Snapshot snapshot() {
    Snapshot result{witness::applies.load(), witness::restores.load(), witness::caller_applies.load(), {}};
    for (size_t i = 0; i < result.cpus.size(); ++i) result.cpus[i] = witness::per_cpu[i].load();
    return result;
}
inline void check(const Snapshot& before, int run, const char* phase) {
    const auto after = snapshot();
    if (after.applies - before.applies != 6 || after.restores - before.restores != 6 ||
        after.caller - before.caller != 1 || witness::errors || witness::active || witness::outside)
        throw std::runtime_error("per-callback placement count or cleanup failed");
    Record record{run, phase, {}, {}};
    std::set<int> cores;
    for (size_t cpu = 0; cpu < after.cpus.size(); ++cpu) {
        const auto delta = after.cpus[cpu] - before.cpus[cpu];
        if (!delta) continue;
        if (delta != 1 || physical_core[cpu] < 0 || !cores.insert(physical_core[cpu]).second)
            throw std::runtime_error("callback did not use distinct physical cores");
        record.cpus.push_back(int(cpu));
        record.cores.push_back(physical_core[cpu]);
    }
    if (record.cpus.size() != 6) throw std::runtime_error("wrong callback target count");
    records.push_back(std::move(record));
}
inline void print() {
    std::cout << '[';
    for (size_t i = 0; i < records.size(); ++i) {
        if (i) std::cout << ',';
        const auto& r = records[i];
        std::cout << "{\"run\":" << r.run << ",\"phase\":\"" << r.phase << "\",\"applies\":6,\"restores\":6,\"caller_applies\":1,\"cpus\":[";
        for (size_t j = 0; j < r.cpus.size(); ++j) { if (j) std::cout << ','; std::cout << r.cpus[j]; }
        std::cout << "],\"physical_cores\":[";
        for (size_t j = 0; j < r.cores.size(); ++j) { if (j) std::cout << ','; std::cout << r.cores[j]; }
        std::cout << "]}";
    }
    std::cout << ']';
}
}

