from pathlib import Path
import subprocess,json,hashlib,datetime,sys,os
root=Path(__file__).resolve().parent
state={'status':'running','commands':[],'started_utc':datetime.datetime.now(datetime.timezone.utc).isoformat()}
report=root/'supplement-run.json'
assert not report.exists()
manifest=json.loads((root/'source-manifest.json').read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def check():assert all(sha(root/p)==h for p,h in manifest['files'].items())
def save():report.write_text(json.dumps(state,indent=2)+'\n',encoding='ascii')
try:
    check()
    for name,args in [('build-followup',['cmd','/c',str(root/'build-followup.bat')]),('followup',[sys.executable,'-B','-X','utf8',str(root/'run-followup.py'),'--output',str(root/'followup-results')]),('eight-driver',[sys.executable,'-B','-X','utf8',str(root/'eight-regression.py')])]:
        row={'name':name,'args':args};state['commands'].append(row)
        with (root/(name+'.stdout')).open('wb') as so,(root/(name+'.stderr')).open('wb') as se:
            p=subprocess.Popen(args,cwd=root,stdout=so,stderr=se,env=dict(os.environ,PYTHONDONTWRITEBYTECODE='1'))
            row['pid']=p.pid;save();print('RUN',name,p.pid,flush=True);row['exit_code']=p.wait()
        row['stdout_sha256']=sha(root/(name+'.stdout'));row['stderr_sha256']=sha(root/(name+'.stderr'))
        save();print('EXIT',name,row['exit_code'],flush=True)
        if row['exit_code']:raise RuntimeError(name+' failed; outputs preserved')
    check();state['status']='pass';state['source_identities_verified']=len(manifest['files'])
except BaseException as e:state.update(status='failed',error=repr(e));raise
finally:state['finished_utc']=datetime.datetime.now(datetime.timezone.utc).isoformat();save()

